const fs = require('fs');
const { filterFarmsForSchedule } = require('/data/shared/rotem/lib/compare-anomaly.js');

let webhookRan = false;
try { webhookRan = $('Webhook Trigger').isExecuted === true; } catch {}
const manual =
  (typeof $execution !== 'undefined' && ['manual', 'test', 'cli', 'webhook'].includes($execution.mode)) ||
  ($('Manual Test Trigger').isExecuted === true) ||
  webhookRan;

const config = JSON.parse(fs.readFileSync('/data/shared/rotem/farms.json', 'utf8'));
const thresholds = JSON.parse(fs.readFileSync('/data/shared/rotem/thresholds.json', 'utf8'));

const farms = (config.farms || []).filter((farm) => {
  if (manual) return true;
  return filterFarmsForSchedule([farm], farm.timezone);
});

if (farms.length === 0) {
  return [{ json: { skipped: true, reason: manual ? 'no_farms_configured' : 'no_farms_due_this_hour' } }];
}

return farms.map((farm) => ({
  json: {
    farm,
    config,
    thresholds,
    manual,
    skipScheduleCheck: manual,
    skipped: false,
  },
}));

const fs = require('fs');
const path = require('path');

const item = $input.item.json;
if (item.skipped || !item.email) {
  return { json: { ...item, skipped: true, reason: item.reason || 'missing_email' } };
}
const email = item.email;

const outbox = '/data/shared/rotem/outbox';
fs.mkdirSync(outbox, { recursive: true });
const slug = `${item.farmId}-${Date.now()}`;
const htmlPath = path.join(outbox, `${slug}.html`);
const metaPath = path.join(outbox, `${slug}.meta.json`);

fs.writeFileSync(htmlPath, email.html);
fs.writeFileSync(path.join(outbox, `${slug}.txt`), email.text);
fs.writeFileSync(
  metaPath,
  JSON.stringify(
    {
      to: email.to,
      from: email.from,
      subject: email.subject,
      farmId: item.farmId,
      alertCount: item.report?.alertCount ?? 0,
      savedAt: new Date().toISOString(),
    },
    null,
    2,
  ),
);

return {
  json: {
    ...item,
    outboxPath: htmlPath,
    outboxMetaPath: metaPath,
  },
};

const fs = require('fs');
const { sendEmail } = require('/data/shared/rotem/lib/email-sender.js');

const item = $input.item.json;
const email = item.email;
if (item.skipped || !email) {
  return { json: { ...item, emailSent: false, emailError: item.reason || 'Missing email payload' } };
}

const config = JSON.parse(fs.readFileSync('/data/shared/rotem/farms.json', 'utf8'));
const smtp = { ...(config.smtp || {}), useApi: true };

try {
  const result = await sendEmail(email, smtp);
  return {
    json: {
      ...item,
      emailSent: true,
      emailProvider: result.provider,
      emailId: result.id,
    },
  };
} catch (err) {
  return {
    json: {
      ...item,
      emailSent: false,
      emailError: err.message,
    },
  };
}

const fs = require('fs');
const { buildFailureEmail } = require('/data/shared/rotem/lib/email-builder.js');

const item = $input.item.json || {};
let itemError = null;
try {
  itemError = $input.item.error || null;
} catch {}

let config = {};
try {
  config = JSON.parse(fs.readFileSync('/data/shared/rotem/farms.json', 'utf8'));
} catch {}

let queuedFarm = null;
try {
  queuedFarm = $('Any Farms Due?').item.json.farm || null;
} catch {}

let stamp = item.libStamp || '';
if (!stamp) {
  try {
    stamp = fs
      .readFileSync('/data/shared/rotem/IMAGE_STAMP.txt', 'utf8')
      .trim()
      .split('\n')
      .slice(0, 4)
      .join(' | ');
  } catch {
    stamp = 'IMAGE_STAMP missing';
  }
}

const email = buildFailureEmail({
  item,
  itemError,
  farm: queuedFarm,
  config,
  stamp,
});

return {
  json: {
    ...item,
    farmId: item.farmId || (queuedFarm && queuedFarm.id) || null,
    farmName: item.farmName || (queuedFarm && queuedFarm.displayName) || item.farmId,
    libStamp: stamp,
    message: email.causeDetail,
    email,
  },
};

